package glitch

import data.glitch_lib

sensitive_properties := {"password", "secret", "token", "key", "credential", "auth"}

default_credentials := {"password", "123456", "changeme", "admin", "default", "demo-key"}

check_sensitive_property(name) {
    regex.match("(?i).*(password|secret|token|key|credential|auth).*", name)
}

check_hardcoded_value(value) {
    value.ir_type == "String"
    value.value != ""
    not startswith(value.value, "$")
    not startswith(value.value, "{{")
    not startswith(value.value, "vault(")
    not startswith(value.value, "secret(")
}

check_default_credentials(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    default_credentials[_] == lower_value
}

check_uri_with_credentials(value) {
    value.ir_type == "String"
    regex.match(".*://[^:]+:[^@]+@.*", value.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_sensitive_property(attr.name)
    check_hardcoded_value(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded password in Infrastructure as Code - Avoid storing passwords directly in code. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_sensitive_property(attr.name)
    check_default_credentials(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Default credentials in Infrastructure as Code - Avoid using default or trivial passwords. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
