    check_uri_with_credentials(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Credentials embedded in URI - Avoid hard-coding credentials in connection strings. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    check_sensitive_property(var.name)
    check_hardcoded_value(var.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Hard-coded password in environment variable - Avoid storing passwords directly in code. (CWE-259)"
    }
}

