package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check Variables
    var := parent.variables[_]

    # Look for variable names containing sensitive keywords
    sensitive_var_names := {"password", "secret", "token", "key", "credential", "auth"}
    contains_sensitive_name := some name in sensitive_var_names {
        regex.match(sprintf("(?i).*%s.*", [name]), var.name)
    }

    # Check if the value is a string literal (hard-coded)
    var.value.ir_type == "String"

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Hard-coded password in variable - Avoid storing passwords as literal strings in code. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check Attributes
    attr := glitch_lib.all_attributes(parent)[_]

    # Look for attribute names containing sensitive keywords
    sensitive_attr_names := {"password", "secret", "token", "key", "credential", "auth"}
    contains_sensitive_name := some name in sensitive_attr_names {
        regex.match(sprintf("(?i).*%s.*", [name]), attr.name)
    }

    # Check if the value is a string literal (hard-coded)
    attr.value.ir_type == "String"

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded password in attribute - Avoid storing passwords as literal strings in code. (CWE-259)"
    }
}

