    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check nested hashes within variables (e.g., Ansible dictionaries)
    var := parent.variables[_]

    # Recursively search for key-value pairs in hashes
    walk(var.value, [path, n])
    n.ir_type == "Hash"

    # Check each key-value pair in the hash
    pair := n.value[_]
    key := pair.key
    value := pair.value

